import{_ as e,o as a,c as n,ah as o}from"./chunks/framework.BsNNkeaH.js";const p=JSON.parse('{"title":"Homepage","description":"","frontmatter":{"layout":"doc"},"headers":[],"relativePath":"en/guide/admin/page-accueil.md","filePath":"src/en/guide/admin/page-accueil.md"}'),s={name:"en/guide/admin/page-accueil.md"};function r(i,t,l,h,g,d){return a(),n("div",null,[...t[0]||(t[0]=[o('<h1 id="homepage" tabindex="-1">Homepage <a class="header-anchor" href="#homepage" aria-label="Permalink to &quot;Homepage&quot;">​</a></h1><p>The homepage is what families and visitors see when they reach your school&#39;s address, before signing in. It is configured from <strong>Administration → Homepage</strong>.</p><p>It can contain four parts:</p><table tabindex="0"><thead><tr><th>Part</th><th>Content</th><th>When it is shown</th></tr></thead><tbody><tr><td><strong>Header</strong></td><td>Logo, tagline, subtitle and buttons</td><td>Always</td></tr><tr><td><strong>About</strong></td><td>A title, some text and an image</td><td>Once it has content, if <strong>Show</strong> is ticked</td></tr><tr><td><strong>Departments</strong></td><td>Cards (title, description, image) presenting what you offer</td><td>Once it has a card, if <strong>Show</strong> is ticked</td></tr><tr><td><strong>Frequently asked questions</strong></td><td>Questions and their answers, which open on click</td><td>Once it has a question, if <strong>Show</strong> is ticked</td></tr></tbody></table><p>The <strong>View page</strong> button, top right, opens the homepage in a new tab so you can check the result.</p><h2 id="what-visitors-see-while-nothing-is-configured" tabindex="-1">What visitors see while nothing is configured <a class="header-anchor" href="#what-visitors-see-while-nothing-is-configured" aria-label="Permalink to &quot;What visitors see while nothing is configured&quot;">​</a></h2><p>An empty section never appears: no sample text is ever shown to families. Without configuration, the page is therefore just the header, with your logo, the tagline and two buttons.</p><p>As long as no section is shown, a banner appears at the top of the homepage for <strong>administrators only</strong>: &quot;Your homepage only shows the essentials&quot;. Its <strong>Set it up</strong> button leads to the editor. Visitors don&#39;t see it.</p><h2 id="tracking-each-part-s-state" tabindex="-1">Tracking each part&#39;s state <a class="header-anchor" href="#tracking-each-part-s-state" aria-label="Permalink to &quot;Tracking each part&#39;s state&quot;">​</a></h2><p>At the top of the editor, four tiles sum up each part&#39;s state; the same state is repeated at the top of each block:</p><ul><li><strong>Always shown</strong>: the header;</li><li><strong>Shown</strong>: the part has content and appears on the page;</li><li><strong>Hidden</strong>: the part has content, but <strong>Show this section on the page</strong> is unticked;</li><li><strong>Empty, not shown</strong>: there is nothing to show yet.</li></ul><p>Hiding a part lets you prepare it at your own pace, for instance writing the whole FAQ, before publishing it by ticking the box.</p><h2 id="writing-in-several-languages" tabindex="-1">Writing in several languages <a class="header-anchor" href="#writing-in-several-languages" aria-label="Permalink to &quot;Writing in several languages&quot;">​</a></h2><p>Each text is entered once per app language (fields carry an <strong>FR</strong> or <strong>EN</strong> label). You can fill in just one: a visitor browsing the page in the other language then sees that text rather than an empty part.</p><h2 id="header" tabindex="-1">Header <a class="header-anchor" href="#header" aria-label="Permalink to &quot;Header&quot;">​</a></h2><ul><li><strong>Logo</strong>: this is the school&#39;s logo, the same one as in the menu. It is changed in the settings (<strong>Change the logo</strong> button), see <a href="/en/guide/admin/parametres-application.html">App settings</a>.</li><li><strong>Tagline</strong> and <strong>Subtitle</strong>: the two lines shown below the logo. Leave a field empty to keep the default text in that language.</li><li><strong>Buttons</strong>: they aren&#39;t configurable. <ul><li><strong>Enrol my child</strong> opens the online enrolment form. Requests sent reach the office, see <a href="/en/guide/secretariat/candidatures.html">Applications</a>.</li><li><strong>Log in</strong> leads to the sign-in page. A user who is already signed in sees <strong>My space</strong> instead.</li></ul></li></ul><p>Click <strong>Save changes</strong> to apply the tagline and subtitle.</p><h2 id="about" tabindex="-1">About <a class="header-anchor" href="#about" aria-label="Permalink to &quot;About&quot;">​</a></h2><p>The part where you introduce the school: its history, its vision, what sets it apart.</p><ol><li>Tick <strong>Show this section on the page</strong>.</li><li>Fill in the <strong>Title</strong> and the <strong>Text</strong>. Leave a blank line between two paragraphs.</li><li>Optionally add an <strong>Image</strong> with <strong>Choose an image</strong>: PNG, JPG or WebP, 4 MB maximum. Landscape works best.</li><li>Click <strong>Save changes</strong>.</li></ol><p>The image is only uploaded when you save. <strong>Replace</strong> picks another one; <strong>Remove image</strong> deletes it, also on the next save. Without an image, the text is centred across the full width.</p><h2 id="departments" tabindex="-1">Departments <a class="header-anchor" href="#departments" aria-label="Permalink to &quot;Departments&quot;">​</a></h2><p>One card per department, track or cycle. Cards are <strong>free-form</strong>: they aren&#39;t linked to the departments in <a href="/en/guide/admin/structure-etablissement.html">School structure</a>. You can therefore present your offer the way you want, for instance a single &quot;Preschool and primary&quot; card, or a card for an option that isn&#39;t a department.</p><h3 id="adding-a-card" tabindex="-1">Adding a card <a class="header-anchor" href="#adding-a-card" aria-label="Permalink to &quot;Adding a card&quot;">​</a></h3><ol><li>Click <strong>Add a card</strong>.</li><li>Fill in the <strong>Title</strong> (required, in at least one language), the <strong>Description</strong> and, if you wish, an <strong>Image</strong>.</li><li>Click <strong>Save</strong>.</li></ol><p>A card without an image shows the first letter of its title on a background in the school&#39;s colors.</p><h3 id="organising-cards" tabindex="-1">Organising cards <a class="header-anchor" href="#organising-cards" aria-label="Permalink to &quot;Organising cards&quot;">​</a></h3><ul><li>The <strong>Move up</strong> and <strong>Move down</strong> arrows change the display order.</li><li><strong>Edit</strong> reopens the card; <strong>Delete</strong> removes it permanently, along with its image.</li><li><strong>Section title</strong> replaces &quot;Our departments&quot;; leave it empty to keep that title.</li></ul><h2 id="frequently-asked-questions" tabindex="-1">Frequently asked questions <a class="header-anchor" href="#frequently-asked-questions" aria-label="Permalink to &quot;Frequently asked questions&quot;">​</a></h2><p>The questions families ask most often: school hours, canteen, payment arrangements, enrolment steps…</p><ol><li>Click <strong>Add a question</strong>.</li><li>Fill in the <strong>Question</strong> and the <strong>Answer</strong>, both required in at least one language.</li><li>Click <strong>Save</strong>.</li></ol><p>On the homepage, only the questions are visible; the answer opens when the visitor clicks on it. The arrows, <strong>Edit</strong>, <strong>Delete</strong> and the <strong>Section title</strong> work as they do for departments.</p><div class="tip custom-block"><p class="custom-block-title">TIP</p><p>Saving is immediate: as soon as you click <strong>Save</strong>, the public homepage is up to date.</p></div>',33)])])}const u=e(s,[["render",r]]);export{p as __pageData,u as default};
